            assert false;
        } catch (Exception e) {
            assertThat(e, instanceOf(Exception.class));
        }
    }

    @Test
    public void testSeal() throws Exception{
        namespaceResolver.seal();
        assertTrue(namespaceResolver.isSealed());
    }

