        unionContext = new UnionContext(mock(EvalContext.class), contexts);
    }

    @Test
    public void testSetPosition_PreparedFalse_ReturnsTrue(){
        // Arrange
        when(unionContext.super.setPosition(10)).thenReturn(true);

        // Act
        boolean result = unionContext.setPosition(10);

        // Assert
        assertTrue(result);
    }

    @Test
    public void testSetPosition_PreparedFalse_ReturnsFalse(){
        // Arrange
        when(unionContext.super.setPosition(10)).thenReturn(false);

        // Act
        boolean result = unionContext.setPosition(10);

        // Assert
        assertFalse(result);
    }

    @Test
    public void testSetPosition_PreparedTrue_ReturnsSuperSetPosition(){
        // Arrange
        unionContext.prepared = true;
        when(unionContext.super.setPosition(10)).thenReturn(true);

        // Act
        boolean result = unionContext.setPosition(10);

        // Assert
        assertTrue(result);
    }

    @Test
    public void testSetPosition_AddsPointersToNodeSet(){
        // Arrange
        EvalContext ctx = mock(EvalContext.class);
        when(ctx.nextSet()).thenReturn(true);
        when(ctx.nextNode()).thenReturn(true);
        NodePointer ptr = mock(NodePointer.class);
        when(ctx.getCurrentNodePointer()).thenReturn(ptr);

        unionContext.contexts = new EvalContext[]{ctx};

        // Act
        unionContext.setPosition(10);

        // Assert
        BasicNodeSet nodeSet = (BasicNodeSet) unionContext.getNodeSet();
        assertEquals(1, nodeSet.size());
    }

    @Test
    public void testSetPosition_SortsPointers(){
        // Arrange
        EvalContext ctx1 = mock(EvalContext.class);
        when(ctx1.nextSet()).thenReturn(true);
        when(ctx1.nextNode()).thenReturn(true);
        NodePointer ptr1 = mock(NodePointer.class);
        when(ctx1.getCurrentNodePointer()).thenReturn(ptr1);
        when(ptr1.getDocumentOrder()).thenReturn(10);

        EvalContext ctx2 = mock(EvalContext.class);
        when(ctx2.nextSet()).thenReturn(true);
        when(ctx2.nextNode()).thenReturn(true);
        NodePointer ptr2 = mock(NodePointer.class);
        when(ctx2.getCurrentNodePointer()).thenReturn(ptr2);
        when(ptr2.getDocumentOrder()).thenReturn(5);

        unionContext.contexts = new EvalContext[]{ctx1, ctx2};

        // Act
        unionContext.setPosition(10);

        // Assert
        BasicNodeSet nodeSet = (BasicNodeSet) unionContext.getNodeSet();
        Iterator<Pointer> iterator = nodeSet.iterator();
        assertEquals(5, iterator.next().getDocumentOrder());
        assertEquals(10, iterator.next().getDocumentOrder());
    }

    @Test
    public void testSetPosition_DoesNotAddDuplicatePointers(){
        // Arrange
        EvalContext ctx = mock(EvalContext.class);
        when(ctx.nextSet()).thenReturn(true);
        when(ctx.nextNode()).thenReturn(true);
        NodePointer ptr = mock(NodePointer.class);
        when(ctx.getCurrentNodePointer()).thenReturn(ptr);

        unionContext.contexts = new EvalContext[]{ctx};

        // Act
        unionContext.setPosition(10);
        unionContext.setPosition(10);

        // Assert
        BasicNodeSet nodeSet = (BasicNodeSet) unionContext.getNodeSet();
        assertEquals(1, nodeSet.size());
    }
}
